pplyFunction(CFRange range, CFArrayApplierFunction applier, void* context) const;	CFIndex GetFirstIndexOfValue(CFRange range, const void* value) const;	CFIndex GetLastIndexOfValue(CFRange range, const void* value) const;	CFIndex BSearchValues(CFRange range, const void* value, 						  CFComparatorFunction comparator, void* context) const;	// CFMutableArray wrappings	static CFMutableArrayRef CreateMutable(CFAllocatorRef allocator, CFIndex capacity, const CFArrayCallBacks* callBacks);	static CFMutableArrayRef CreateMutableCopy(CFAllocatorRef allocator, CFIndex capacity, CFArrayRef theArray);	void AppendValue(const void* value);	void InsertValueAtIndex(CFIndex idx, const void* value);	void SetValueAtIndex(CFIndex idx, const void* value);	void RemoveValueAtIndex(CFIndex idx);	void RemoveAllValues();	void ReplaceValues(CFRange range, const void** newValues, CFIndex newCount);	void ExchangeValuesAtIndices(CFIndex idx1, CFIndex idx2);	void SortValues(CFRange range, CFComparatorFunction comparator, void* context);#if qCarbonSDKVersion >= qVersion1_1	void AppendArray(CFArrayRef otherArray, CFRange otherRange);#endif};//========================================================================================// CAutoCFArray_AC//========================================================================================class CAutoCFArray_AC : public TemplateAutoRef_AC<CFArrayRef>{public:	CAutoCFArray_AC();	CAutoCFArray_AC(CFArrayRef array);	CAutoCFArray_AC(const void** values, CFIndex numValues, const CFArrayCallBacks* callBacks);	CAutoCFArray_AC(CFAllocatorRef allocator, CFArrayRef theArray);	CAutoCFArray_AC(const TemplateAutoRef_AC<CFArrayRef>& from);	~CAutoCFArray_AC();};//========================================================================================// CAutoCFMutableArray_AC//========================================================================================class CAutoCFMutableArray_AC : public TemplateAutoRef_AC<CFMutableArrayRef>{public:	CAutoCFMutableArray_AC();	CAutoCFMutableArray_AC(CFMutableArrayRef array);	CAutoCFMutableArray_AC(CFIndex capacity, const CFArrayCallBacks* callBacks);	CAutoCFMutableArray_AC(CFIndex capacity, CFArrayRef theArray);	CAutoCFMutableArray_AC(const TemplateAutoRef_AC<CFMutableArrayRef>& from);	~CAutoCFMutableArray_AC();};//========================================================================================// __CFArray//========================================================================================inline CFIndex __CFArray::GetCount() const{	return CFArrayGetCount(this);}inline CFIndex __CFArray::GetCountOfValue(CFRange range, const void* value) const{	return CFArrayGetCountOfValue(this, range, value);}inline bool __CFArray::ContainsValue(CFRange range, const void* value) const{	return CFArrayContainsValue(this, range, value);}inline const void* __CFArray::GetValueAtIndex(CFIndex idx) const{	return CFArrayGetValueAtIndex(this, idx);}inline void __CFArray::GetValues(CFRange range, const void** values) const{	CFArrayGetValues(this, range, values);}inline void __CFArray::ApplyFunction(CFRange range, CFArrayApplierFunction applier, void* context) const{	CFArrayApplyFunction(this, range, applier, context);}inline CFIndex __CFArray::GetFirstIndexOfValue(CFRange range, const void* value) const{	return CFArrayGetFirstIndexOfValue(this, range, value);}inline CFIndex __CFArray::GetLastIndexOfValue(CFRange range, const void* value) const{	return CFArrayGetLastIndexOfValue(this, range, value);}inline CFIndex __CFArray::BSearchValues(CFRange range, const void* value, 										  CFComparatorFunction comparator, void* context) const{	return CFArrayBSearchValues(this, range, value, comparator, context);}inline void __CFArray::AppendValue(const void* value){	CFArrayAppendValue(this, value);}inline void __CFArray::InsertValueAtIndex(CFIndex idx, const void* value){	CFArrayInsertValueAtIndex(this, idx, value);}inline void __CFArray::SetValueAtIndex(CFIndex idx, const void* value){	CFArraySetValueAtIndex(this, idx, value);}inline void __CFArray::RemoveValueAtIndex(CFIndex idx){	CFArrayRemoveValueAtIndex(this, idx);}inline void __CFArray::RemoveAllValues(){	CFArrayRemoveAllValues(this);}inline void __CFArray::ReplaceValues(CFRange range, const void** newValues, CFIndex newCount){	CFArrayReplaceValues(this, range, newValues, newCount);}inline void __CFArray::ExchangeValuesAtIndices(CFIndex idx1, CFIndex idx2){	CFArrayExchangeValuesAtIndices(this, idx1, idx2);}inline void __CFArray::SortValues(CFRange range, CFComparatorFunction comparator, void* context){	CFArraySortValues(this, range, comparator, context);}#if qCarbonSDKVersion >= qVersion1_1inline void __CFArray::AppendArray(CFArrayRef otherArray, CFRange otherRange){	CFArrayAppendArray(this, otherArray, otherRange);}#endif//========================================================================================// CAutoCFArray_AC//========================================================================================inline CAutoCFArray_AC::CAutoCFArray_AC()	:	TemplateAutoRef_AC<CFArrayRef>(NULL){}inline CAutoCFArray_AC::CAutoCFArray_AC(CFArrayRef array)	:	TemplateAutoRef_AC<CFArrayRef>(array){}inline CAutoCFArray_AC::CAutoCFArray_AC(const void** values, CFIndex numValues,										const CFArrayCallBacks* callBacks)	:	TemplateAutoRef_AC<CFArrayRef>(__CFArray::Create(NULL, values, numValues, callBacks)){}inline CAutoCFArray_AC::CAutoCFArray_AC(CFAllocatorRef allocator, CFArrayRef theArray)	:	TemplateAutoRef_AC<CFArrayRef>(__CFArray::CreateCopy(allocator, theArray)){}inline CAutoCFArray_AC::CAutoCFArray_AC(const TemplateAutoRef_AC<CFArrayRef>& from)	:	TemplateAutoRef_AC<CFArrayRef>(from){}inline CAutoCFArray_AC::~CAutoCFArray_AC(){}//========================================================================================// CAutoCFMutableArray_AC//========================================================================================inline CAutoCFMutableArray_AC::CAutoCFMutableArray_AC()	:	TemplateAutoRef_AC<CFMutableArrayRef>(){}inline CAutoCFMutableArray_AC::CAutoCFMutableArray_AC(CFMutableArrayRef array)	:	TemplateAutoRef_AC<CFMutableArrayRef>(array){}inline CAutoCFMutableArray_AC::CAutoCFMutableArray_AC(CFIndex capacity, const CFArrayCallBacks* callBacks)	:	TemplateAutoRef_AC<CFMutableArrayRef>(__CFArray::CreateMutable(NULL, capacity, callBacks)){}inline CAutoCFMutableArray_AC::CAutoCFMutableArray_AC(CFIndex capacity, CFArrayRef theArray)	:	TemplateAutoRef_AC<CFMutableArrayRef>(__CFArray::CreateMutableCopy(NULL, capacity, theArray)){}inline CAutoCFMutableArray_AC::CAutoCFMutableArray_AC(const TemplateAutoRef_AC<CFMutableArrayRef>& from)	:	TemplateAutoRef_AC<CFMutableArrayRef>(from){}inline CAutoCFMutableArray_AC::~CAutoCFMutableArray_AC(){}#endif // __CCFArray_AC__